ResultAnalysist::ResultAnalysist()
{
    this->clear();
}

void ResultAnalysist::clear()
{
    this->lastSphR = 0;
    this->lastSphL = 0;
    this->lastCylR = 0;
    this->lastCylL = 0;
    this->lastRightPd = 0;
    this->lastLeftPd = 0;
    this->lastPd = 0;
    this->judgeState = false;
}

void ResultAnalysist::loadResult(double _sphL, double _cylL, double _sphR, double _cylR, int _Pd, double _leftPd, double _rightPd)
{
    this->lastSphR = _sphR;
    this->lastSphL = _sphL;
    this->lastCylR = _cylR;
    this->lastCylL = _cylL;
    this->lastPd   = _Pd;
    this->lastLeftPd = _leftPd;
    this->lastRightPd = _rightPd;
}

// 检查当前被测者和上一个被测者是否同一人？
bool ResultAnalysist::judgePatient(int _Pd, double _leftPd, double _rightPd)
{
    int pdDiffer = abs(_Pd - lastPd);
    double leftPd_Differ = fabs(_leftPd - lastLeftPd);
    double rightPd_Differ = fabs(_rightPd - lastRightPd);

    if(pdDiffer <= 13 && leftPd_Differ <= 1.3 && rightPd_Differ <= 1.3)
    {
        qDebug() << "--same guy";
        this->judgeState = true;
        return true;
    }
    else
    {
        qDebug() << "--not the same guy:\nlast:" << lastPd << "," << lastLeftPd << "," << lastRightPd << ",current:" << _Pd << "," << _leftPd << "," << _rightPd;
        this->clear();
        this->judgeState = false;

        return false;
    }

}

// 将本次测量结果和上一次做平均，使结果稳定
void ResultAnalysist::GetStableResult(double &_sphL, double &_cylL, double &_sphR, double &_cylR)
{
    double sphL_Differ = fabs(_sphL - lastSphL);
    double sphR_Differ = fabs(_sphR - lastSphR);
    double cylL_Differ = fabs(_cylL - lastCylL);
    double cylR_Differ = fabs(_cylR - lastCylR);

    if(sphL_Differ <= 0.75 && sphR_Differ <= 0.75 && cylL_Differ <= 0.75 && cylR_Differ <= 0.75)
    {
        _sphL = (_sphL + lastSphL) / 2;
        _sphR = (_sphR + lastSphR) / 2;
        _cylL = (_cylL + lastCylL) / 2;
        _cylR = (_cylR + lastCylR) / 2;

        qDebug() << "--GetStableResult";
    }
    else
    {
        qDebug() << "-->0.75 noNeedToGetStableResult";
    }
}

