bool AlgorithmThread::crudeAlgorithm(unsigned char *pFrameBuffer, int _img_idx, stPupilInfo &_pupil_info_r, stPupilInfo &_pupil_info_l)  //饱和度计算
{
    bool succ = false;

    int feedback = 0;
    do {
        gResult[0] = 1;
        gResult[1] = 1;
        gResult[2] = 1;
        gResult[3] = 1;
        gResult[4] = 1;

        IplImage *Img = cvCreateImageHeader(cvSize(IMG_WIDTH, IMG_HEIGHT), IPL_DEPTH_8U, 1);
        cvSetData(Img, pFrameBuffer, IMG_WIDTH);

        if (Img == NULL)
        {
            logCritical("AlgorithmThread::crudeAlgorithm(): Img should not be NULL!", CGlobal::LOG_ALGO);
            break;
        }

        CvPoint3D32f avalPoint3D[2];
        int pupilDis = 0;
        double MaxValue = 0.0;

        //1. PYR DOWN and detect Pupil Location
        string r_stat = "";
        if (CGlobal::isExternalControl)  //2020.10.12  tao
        {
            WinMeasure::getRunStat(r_stat);
            if(WinMeasure::old_run_stat != r_stat)
            {
                //UpLoadThread::sendRunStat(r_stat);
                WinMeasure::setRunStat(DETECT_PUPIL);
            }
        }

        try {
            feedback = blurpyrDetect(Img, avalPoint3D, &pupilDis, &MaxValue, _pupil_info_r, _pupil_info_l);
        }
        catch (exception &ex) {
            logCritical(QString::asprintf("AlgorithmThread::crudeAlgorithm(), executing blurpyrDetect() exception:\n %s", ex.what()), CGlobal::LOG_ALGO);
            output_trace<void>();
            //throw "caught error in AlgorithmThread::crudeAlgorithm() executing blurpyrDetect()";
            feedback = 0;
        }
        catch (...) {
            logCritical(QString::asprintf("AlgorithmThread::crudeAlgorithm(), executing blurpyrDetect() exception: unknown"), CGlobal::LOG_ALGO);
            output_trace<void>();
            //throw "caught error in AlgorithmThread::crudeAlgorithm() executing blurpyrDetect()";
            feedback = 0;
        }

        if (feedback == 1)
        {
            succ = true;

            //
            g_PupilState = 0;
            bSpotCoarseLocationCnt = 0;
        }
        else
        {
            qDebug() << "crudeAlgorithm+++++++++feedback != 1";
            cvReleaseImageHeader(&Img);
    //        cvReleaseImage(&Img);
    //        //qDebug()<<"crudeAlgorithm+++++++++cvReleaseImage++++++123++++end";
            break;
        }

        //
        cvReleaseImageHeader(&Img);

    } while (false);

    //
    return succ;
}

