/**
 * 识别 ROI 图像中的瞳孔（粗略识别或精确识别）
 * @param _is_roughly   是否粗略识别
 * @param _redu_ratio   图像的缩小倍数
 */
bool AlgorithmThread::detectPupilOfImgRoi(IplImage *_img_roi, int _img_idx, stPupilInfo &_pupil_info, bool _is_calc_vision,
                                        enWhichEye _which_eye, bool _is_roughly, int _redu_ratio)
{
    logDebug(QString::asprintf("AlgorithmThread::detectPupilSingle() into ... img idx = %d, which_eye = %d", _img_idx, _which_eye), CGlobal::LOG_ALGO);

    static const int MAX_COUNTOURS = 300;

    bool is_succ = false;

    CvMemStorage *mem_storage = cvCreateMemStorage(0);
    CvSeq *contours = NULL;

    int count_contours = getSinglePupilContours(_img_roi, _img_idx, mem_storage, &contours, _is_calc_vision, _which_eye, _is_roughly, _redu_ratio);
    logDebug(QString::asprintf("AlgorithmThread::detectPupilSingle(): contours count = %d", count_contours), CGlobal::LOG_ALGO);
    if (count_contours > 0 /*&& count_contours < MAX_COUNTOURS*/) {
        bool succ_filter = filterSinglePupilContours(_img_roi, _img_idx, &contours, _pupil_info, _is_calc_vision, _which_eye, _is_roughly, _redu_ratio);
        is_succ = succ_filter;
    }

    //
    //cvClearMemStorage(mem_storage);
    cvReleaseMemStorage(&mem_storage);

    // 如果瞳孔识别失败，以映光点坐标作为瞳孔中心坐标（仅初识别时使用）
    if (_is_roughly && !is_succ) {
        logDebug("AlgorithmThread::detectPupilSingle() >>> !succ, goto detectReflectionSpot() ...", CGlobal::LOG_ALGO);

        //
        CvPoint point_rf;
        bool succ_rf_point = detectReflectionSpotSingle(_img_roi, _img_idx, _which_eye, point_rf);

        //
        if (succ_rf_point) {
            _pupil_info.center = cvPointTo32f(point_rf);
            _pupil_info.radius = (double)(MIN_RADIUS + MAX_RADIUS) / 2 / _redu_ratio;

            if (_is_calc_vision) {
                _pupil_info.rect = cvRect(_pupil_info.center.x - _pupil_info.radius, _pupil_info.center.y - _pupil_info.radius,
                                          _pupil_info.radius * 2, _pupil_info.radius * 2);
            }

            is_succ = true;
        } else {
            logDebug("AlgorithmThread::detectPupilSingle() >>> detectReflectionSpot() failed!", CGlobal::LOG_ALGO);
        }
    }

    logDebug(QString::asprintf("AlgorithmThread::detectPupilSingle() ended ... img idx = %d, which_eye = %d", _img_idx, _which_eye), CGlobal::LOG_ALGO);
    //
    return is_succ;
}

