// 从多组统计视力数据中随机抽出一组
stVisionValue AlgorithmThread::getRandomStatisticalVision(int _age_idx)
{
    // 统计视力数据（前两个年龄段，每个年龄段5组视力数据。数据来源：梁健晖）
    static stVisionValue StatisticalVisions[2][5] = {
        {
            {+2.25, -0.75, 78,  4.2, +1, -1, 48, +2.50, -1.00, 97,  4.2, +3, -1},
            {+2.50, -1.25, 89,  3.8, -1, -1, 45, +2.25, -1.00, 103, 3.8, +1, -1},
            {+2.50, -1.00, 100, 4.6, -3, +1, 50, +3.00, -1.25, 76,  4.6, -1, +1},
            {+2.75, -1.25, 103, 4.2, -4, -3, 48, +2.50, -1.00, 87,  4.2, -1, -3},
            {+2.50, -1.00, 93,  4.2, -3, -1, 48, +3.00, -1.25, 99,  4.6, +3, -1},
        },
        {
            {+2.00, -1.00, 76,  4.8, -2, +1, 49, +2.25, -1.25, 83,  4.8, +2, +2},
            {+2.25, -1.00, 80,  4.4, +1, -1, 47, +2.00, -0.75, 117, 4.4, +4, -1},
            {+2.00, -0.75, 72,  5.0, -2, -2, 52, +1.75, -0.50, 96,  5.0, -1, -1},
            {+2.50, -1.00, 107, 4.8, -1, +2, 47, +2.25, -1.00, 103, 4.8, +1, +2},
            {+1.75, -0.75, 110, 4.4, +1, -1, 49, +2.00, -0.50, 86,  4.4, +2, -1},
        },
    };

    // 是否统计值或月龄屈光值
    visionValueSource = 2;

    //
    int i = rand() % 5;
    if (_age_idx >= 0 && _age_idx <= 1) {
        return StatisticalVisions[_age_idx][i];
    } else {
        logCritical(QString::asprintf("AlgorithmThread::getRandomStatisticalVision(): age group index %d is out of range, the value reterned is false!", _age_idx));
        return StatisticalVisions[1][i];
    }
}

// 设置按月龄估算的屈光度数
/* 参数：*_birth_date：生日。若没有，则传入 nullptr，函数将通过瞳距估算月龄。
 *      如果没有生日，须传入 PD 值。
 */
bool AlgorithmThread::setMonthAgeVisionByBirthday(stVisionValue &_vision, int _age_range, QDate *_birth_date)
{
    int month_age = -1;

    if (_birth_date) {
        // 根据生日计算月龄
        QDate today = QDate::currentDate();
        month_age = (today.year() - _birth_date->year()) * 12 + today.month() - _birth_date->month();
    } else {
        // 根据瞳距估算月龄
        if (_vision.PD > 0) {
            double pd = _vision.PD;

            // 瞳距值限制在 [26, 48] 区间
            if(pd < 26)
                pd = 26;
            else if(pd > 48)
                pd = 48;

            //
            month_age = round(36 * (pd - 26) / (48 - 26));
        }

        // 如果上面算得月龄超出测量时所选年龄段，则等于最接近的年龄段区间边界值
        int min_month_age, max_month_age;
        getMonthBoundaryOfAgeRange(_age_range, min_month_age, max_month_age);

        if (month_age < min_month_age)
            month_age = min_month_age;
        else if (month_age > max_month_age)
            month_age = max_month_age;
    }

    if (month_age > 0) {
        return setMonthAgeVision(_vision, month_age);
    } else {
        return false;
    }
}

bool AlgorithmThread::setMonthAgeVision(stVisionValue &_vision, int _month_age)
{
    struct stMonthAgeDiopter {
        float sph;
        float cyl;
    };

    const int MONTH_AGE_BOUNDS[6][2] = {        /* 数据来源：《20220321_刘宇_视筛0~3岁婴幼儿屈光数值一致性的解决办法.docx》，《开封市1359例婴幼儿屈光状态调查分析_李琳.pdf》 */
        { 6,  9},
        {10, 12},
        {13, 18},
        {19, 24},
        {25, 30},
        {31, 36},
    };

    const stMonthAgeDiopter MONTH_AGE_DIOPTER[] = {
        {+2.00, +1.37},
        {+1.81, +0.97},
        {+1.69, +0.77},
        {+1.69, +0.70},
        {+1.63, +0.79},
        {+1.58, +0.70},
    };

    //
    int idx = -1;
    if (_month_age < 6) {
        idx = 0;
    } else if (_month_age > 36) {
        idx = 5;
    } else {
        for (int i = 0; i < 6; i++) {
            if (_month_age >= MONTH_AGE_BOUNDS[i][0] && _month_age <= MONTH_AGE_BOUNDS[i][1]) {
                idx = i;
                break;
            }
        }
    }

    if (idx >= 0 && idx <=5) {
        float sph = MONTH_AGE_DIOPTER[idx].sph;
        float cyl = MONTH_AGE_DIOPTER[idx].cyl;

        // 正柱镜转为负柱镜
        sph = sph + cyl;
        cyl = -cyl;

        // 随机增减 0.25
        const float VALUE_ADD[3] = {-0.25, 0, +0.25};

        int rand_1 = Util::randomInt() % 3;
        _vision.LSph = sph + VALUE_ADD[rand_1];

        int rand_2 = Util::randomInt() % 3;
        _vision.LCyl = cyl + VALUE_ADD[rand_2];

        int rand_3 = Util::randomInt() % 3;
        _vision.RSph = sph + VALUE_ADD[rand_3];

        int rand_4 = Util::randomInt() % 3;
        _vision.RCyl = cyl + VALUE_ADD[rand_4];

        // 设置轴位值
        setMonthAgeAxis(_vision, _month_age);

        // 是否统计值或月龄屈光值
        visionValueSource = 1;

        //
        return true;
    } else {
        return false;
    }
}

// 获得月龄屈光度的轴位（设计文档：《20220415_梁健晖_前两年龄段轴位问题.docx》）
void AlgorithmThread::setMonthAgeAxis(stVisionValue &_vision, int _month_age)
{
    if (_month_age < 6)
        _month_age = 6;
    if (_month_age > 48)
        _month_age = 48;

    // 用多项时计算轴位
    int axis = _month_age * -1.5 + 99.2;

    // 随机浮动
    int rand_offset_l = Util::randomInt() % 7 - 3;
    int axis_l = axis + rand_offset_l;
    int rand_offset_r = Util::randomInt() % 7 - 3;
    int axis_r = axis + rand_offset_r;

    // 随机翻转 /** 不能随机翻转，否则降低一致性，违背月龄估值的初衷 **/
    //bool is_reverse_l = Util::randomInt() % 2;
    //axis_l = (is_reverse_l ? 180 - axis_l : axis_l);
    //bool is_reverse_r = Util::randomInt() % 2;
    //axis_r = (is_reverse_r ? 180 - axis_r : axis_r);

    //
    _vision.LAx = axis_l;
    _vision.RAx = axis_r;
}

// 得到指定年龄段的最小和最大月龄
void AlgorithmThread::getMonthBoundaryOfAgeRange(int _age_range, int &_min_month_age, int &_max_month_age)
{
    if (_age_range < 0)
        _age_range = 0;
    else if (_age_range > 4)
        _age_range = 4;

    if(0 == _age_range) {           // 6-12个月
        _min_month_age = 6;
        _max_month_age = 12;
    } else if (1 == _age_range) {   // 1-3岁
        _min_month_age = 12;
        _max_month_age = 36;
    } else if (2 == _age_range) {   // 3-6岁
        _min_month_age = 36;
        _max_month_age = 72;
    } else if (3 == _age_range) {   // 6-20岁
        _min_month_age = 72;
        _max_month_age = 240;
    } else if (4 == _age_range) {   // 20-100岁
        _min_month_age = 240;
        _max_month_age = 1200;
    }
}

