// 获取推值（流程见《20220328_“前两年龄段按月龄估值”功能程序设计.docx》）
void AlgorithmThread::getStatisticalValues(int _age_range, stVisionValue &_vision, stVisionValueUnnormal &_value_unnormal)
{
    // 如果不需要按月龄估值，则取统计值，否则取月龄估值
    memset(&_vision, 0, sizeof(stVisionValue));

    // 获取统计值
    _vision = getRandomStatisticalVision(_age_range);

    // 如果需要使用月龄屈光值，则替换
    bool is_need_statistical = !CGlobal::getIsNeedMonthAgeVision(_age_range);
    if (!is_need_statistical) {
        // 检查并设置瞳距
        if (Util::compDouble(g_SaturationCenterL.x, 0) > 0 && Util::compDouble(g_SaturationCenterR.x, 0) > 0) {
            _vision.PD = fabs(g_SaturationCenterL.x - g_SaturationCenterR.x) * PIX_TO_PHY;
        }

        // 获得生日
        QDate birth_date = Util::strToDate(currentPat.patientdate);
        QDate *birth_date_ptr = (birth_date.isValid() ? &birth_date : Q_NULLPTR);

        // 获得月龄屈光值
        setMonthAgeVisionByBirthday(_vision, _age_range, birth_date_ptr);
    }

    //
    g_strabismusValue.leftEyeLR = _vision.LHz * 6;
    g_strabismusValue.leftEyeUD = _vision.LVz * 6;
    g_strabismusValue.rightEyeLR = _vision.RHz * 6;
    g_strabismusValue.rightEyeUD = _vision.RVz * 6;

    //
    memset(&_value_unnormal, 0, sizeof(stVisionValueUnnormal));
}

