//    qDebug()<<"-----------------------------222222222222222222-----------------------------------";
//    cvSaveImage("/media/SpotEhanceSampleImg.bmp",SpotEhanceSampleImg);

//    SpotEnhance(SampleImg, SpotEhanceSampleImg);


    CvPoint bcenter1;
