void AlgorithmThread::FillInternalContours(IplImage *pBinary, double dAreaThre)
{
    qDebug() << "AlgorithmThread::FillInternalContours() into ...";

    double dConArea;
    CvSeq *pContour = NULL;
    CvSeq *pConInner = NULL;
    CvMemStorage *pStorage = NULL;
    // 执行条件
    if (pBinary)
    {
        // 查找所有轮廓
        pStorage = cvCreateMemStorage(0);
        cvFindContours(pBinary, pStorage, &pContour, sizeof(CvContour), CV_RETR_CCOMP, CV_CHAIN_APPROX_SIMPLE);
        // 填充所有轮廓
        cvDrawContours(pBinary, pContour, CV_RGB(255, 255, 255), CV_RGB(255, 255, 255), 2, CV_FILLED, 8, cvPoint(0, 0));
        // 外轮廓循环
        int wai = 0;
        int nei = 0;
        for (; pContour != NULL; pContour = pContour->h_next)
        {
            wai++;
            // 内轮廓循环
            for (pConInner = pContour->v_next; pConInner != NULL; pConInner = pConInner->h_next)
            {
                nei++;
                // 内轮廓面积
                dConArea = fabs(cvContourArea(pConInner, CV_WHOLE_SEQ));
                //				printf("%f\n", dConArea);
                if (dConArea <= dAreaThre)
                {
                    cvDrawContours(pBinary, pConInner, CV_RGB(255, 255, 255), CV_RGB(255, 255, 255), 0, CV_FILLED, 8, cvPoint(0, 0));
                }
            }
        }
        //		printf("wai = %d, nei = %d\n", wai, nei);
        cvReleaseMemStorage(&pStorage);
        pStorage = NULL;
    }

    qDebug() << "AlgorithmThread::FillInternalContours() ended ...";
}


int AlgorithmThread::ConnectEdge(IplImage *src)
{
    qDebug() << "AlgorithmThread::ConnectEdge() into ...";

    if (NULL == src) {
        qDebug() << "AlgorithmThread::ConnectEdge() ended ...";
        return 1;
    }

    int width = src->width;
    int height = src->height;

    uchar *data = (uchar *)src->imageData;
    for (int i = 2; i < height - 2; i++)
    {
        for (int j = 2; j < width - 2; j++)
        {
            //如果该中心点为255,则考虑它的八邻域
            if (data[i * src->widthStep + j] == 255)
            {
                int num = 0;
                for (int k = -1; k < 2; k++)
                {
                    for (int l = -1; l < 2; l++)
                    {
                        //如果八邻域中有灰度值为0的点，则去找该点的十六邻域
                        if (k != 0 && l != 0 && data[(i + k) * src->widthStep + j + l] == 255)
                            num++;
                    }
                }
                //如果八邻域中只有一个点是255，说明该中心点为端点，则考虑他的十六邻域
                if (num == 1)
                {
                    for (int k = -2; k < 3; k++)
                    {
                        for (int l = -2; l < 3; l++)
                        {
                            //如果该点的十六邻域中有255的点，则该点与中心点之间的点置为255
                            if (!(k < 2 && k > -2 && l < 2 && l > -2) && data[(i + k) * src->widthStep + j + l] == 255)
                            {
                                data[(i + k / 2) * src->widthStep + j + l / 2] = 255;
                            }
                        }
                    }
                }
            }
        }
    }

    qDebug() << "AlgorithmThread::ConnectEdge() ended ...";
    return 0;
}

void AlgorithmThread::lhMorpFillHole(const IplImage *src, IplImage *dst)
{
    IplImage *temp = cvCloneImage(src);
    double min, max;
    cvMinMaxLoc(src, &min, &max);

    //标记图像
    cvRectangle(temp, cvPoint(3, 3), cvPoint(temp->width - 7, temp->height - 7), CV_RGB(max, max, max), -1);

//    cvShowImage("temp", temp);
//    cvShowImage("src", src);
//    cvWaitKey(2000);
//    cvDestroyAllWindows();

    //将原图像作为掩模图像
    lhMorpRErode(temp, src, dst, NULL, -1);

    cvReleaseImage(&temp);
}

//形态学测地腐蚀和腐蚀重建运算
void AlgorithmThread::lhMorpRErode(const IplImage *src, const IplImage *msk, IplImage *dst, IplConvKernel *se, int iterations)
{
    assert(src != NULL  && msk != NULL && dst != NULL && src != dst);

    if (iterations < 0)
    {
        //腐蚀重建
        cvMax(src, msk, dst);
        cvErode(dst, dst, se);
        cvMax(dst, msk, dst);

        int width = src->width;
        int height = src->height;
        IplImage  *temp1 = cvCreateImage(cvSize(width, height), 8, 1);
        do
        {
            //record last result
            cvCopy(dst, temp1);
            cvErode(dst, dst, se);
            cvMax(dst, msk, dst);
        }
        while (lhImageCmp(temp1, dst) != 0);

        cvReleaseImage(&temp1);

        return;

    }
    else if (iterations == 0)
    {
        cvCopy(src, dst);
    }
    else
    {
        //普通测地腐蚀 p137(6.2)
        cvMax(src, msk, dst);
        cvErode(dst, dst, se);
        cvMax(dst, msk, dst);

        for (int i = 1; i < iterations; i++)
        {
            cvErode(dst, dst, se);
            cvMax(dst, msk, dst);
        }
    }
}

int AlgorithmThread::lhImageCmp(const IplImage *_img1, const IplImage *_img2)
{
    if (_img1->width != _img2->width || _img1->height != _img2->height || _img1->nChannels != _img2->nChannels) {
        return false;
    }

    if (_img1->width == _img1->width / 4 * 4) {
        return memcmp(_img1->imageData, _img2->imageData, _img1->imageSize);        // opencv 的图像矩阵的行是对齐到 4 的
    } else {
        IplImage *img_temp = cvCreateImage(cvSize(_img1->width, _img1->height), _img1->depth, _img1->nChannels);

        cvCmp(_img1, _img2, img_temp, CV_CMP_NE);
        bool is_same = (cvSum(img_temp).val[0] == 0);

        cvReleaseImage(&img_temp);

        return is_same;
    }
}

