//
void AlgorithmThread::rotateImage(IplImage *img, IplImage *img_rotate, int degree)
{
    //旋转中心为图像中心
    CvPoint2D32f center;
    center.x = float(img->width / 2.0 + 0.5);
    center.y = float(img->height / 2.0 + 0.5);
    //计算二维旋转的仿射变换矩阵
    float m[6];
    CvMat M = cvMat(2, 3, CV_32F, m);
    cv2DRotationMatrix(center, degree, 1, &M);
    //变换图像，并用黑色填充其余值
    cvWarpAffine(img, img_rotate, &M, CV_INTER_LINEAR | CV_WARP_FILL_OUTLIERS, cvScalarAll(0));
}

void AlgorithmThread::SpotEnhance(IplImage *src, IplImage *dst)
{
    qDebug() << "AlgorithmThread::SpotEnhance() into ...";

    int w = src->width;
    int h = src->height;

    IplImage *temp1 = cvCreateImage(cvSize(w, h), IPL_DEPTH_8U, 1);
    IplImage *temp2 = cvCreateImage(cvSize(w, h), IPL_DEPTH_8U, 1);

    // 去除高光
    cvNot(src, temp1);
    lhMorpFillHole(temp1, temp2);
    cvNot(temp2, temp1);

    //cvShowImage("temp1", temp1);

    // 相减得到高光位置
    cvSub(src, temp1, dst);

    cvReleaseImage(&temp1);
    cvReleaseImage(&temp2);

    qDebug() << "AlgorithmThread::SpotEnhance() ended ...";
}

