// 计算图像的平均梯度
double AlgorithmThread::calcAvgGrey(const cv::Mat &_img)
{
    if(_img.channels() != 1)
    {
        std::cout << "输入必须是单通道图像！" << std::endl;
        return 0.0;
    }

    _img.convertTo(_img, CV_64FC1);

    double tmp = 0;
    int rows = _img.rows - 1;
    int cols = _img.cols - 1;
    for(int i = 0; i < rows; i++)
    {
        for(int j = 0; j < cols; j++)
        {
            double dx = _img.at<double>(i, j + 1) - _img.at<double>(i, j);
            double dy = _img.at<double>(i + 1, j) - _img.at<double>(i, j);
            double ds = std::sqrt((dx * dx + dy * dy) / 2);
            tmp = tmp + ds;
        }
    }
    double avg_gray = tmp / (rows * cols);      // TODO: 这里不应该是 (rows  - 1) * (cols - 1) 吗？
    return avg_gray;
}

/*
功能：计算图像的清晰度（来自：向祖松）
参数：grayImage--输入灰度图像
返回：图像的清晰度值，负数表示错误
*/
float AlgorithmThread::calcClarity(const cv::Mat &grayImage)            // TODO: 和 AlgorithmThread::calcClarity() 相比如何？
{
    float clarity = 0.0;

    if (grayImage.empty())
    {
        cout << "image data is null!" << endl;
        return clarity;
    }

    // 计算图像的平均梯度能量值
    int Df = 0;
    int gray = 0;
    for (int i = 0; i < grayImage.rows - 1; i++)
    {
        for (int j = 0; j < grayImage.cols - 1; j++)
        {
            int curGray = grayImage.at<uchar>(i, j);
            int rightGray = grayImage.at<uchar>(i, j + 1);
            int downGray = grayImage.at<uchar>(i + 1, j);
            Df += (curGray - rightGray) * (curGray - rightGray) + (curGray - downGray) * (curGray - downGray);

            gray += curGray;
        }
    }

    double d = (double)Df / (grayImage.rows * grayImage.cols);
    double grayAvg = (double)gray / (grayImage.rows * grayImage.cols);

    //if (abs(grayAvg) < 1e-5)
    //{
    //    cout << "devide by zero" << endl;
    //    return -1.0F;
    //}

    clarity = d / grayAvg;

    return clarity;
}

float AlgorithmThread::calcClarity(unsigned char *_img_data)
{
    cv::Mat img(IMG_HEIGHT, IMG_WIDTH, CV_8UC1, _img_data);
    return calcClarity(img);
}

// 计算均值和标准差
void AlgorithmThread::calcMeanStdDev(const Mat &_img, double &_mean, double &_std_dev)
{
    cv::Mat mat_mean, mat_stddev;
    cv::meanStdDev(_img, mat_mean, mat_stddev);      // TODO: 通过标准差判断衡量对比度，是否合理？
    _mean = mat_mean.ptr<double>(0)[0];
    _std_dev = mat_stddev.ptr<double>(0)[0];
}

void AlgorithmThread::calcMeanStdDev(unsigned char *_img_data, double &_mean, double &_std_dev)
{
    cv::Mat img(IMG_HEIGHT, IMG_WIDTH, CV_8UC1, _img_data);
    calcMeanStdDev(img, _mean, _std_dev);
}

