// 综和度数 转换 为视力
QString AlgorithmThread::seToReferVision(QString _se, int _type)
{
    double val = _se.toDouble();
    QString vision = "";

//    if(val > 0)
//        vision = (language ? "远视 " : "Hyperopia");
//    else if(val < 0)
//        vision = (language ? "近视 " : "Myopia");

    val = abs(val);
    if (visionNotation_FivePoint == _type) {
        if(Util::compDouble(val, 6.75) >= 0) { vision += "<4.0";
        } else if (Util::compDouble(val, 6.25) >= 0 && Util::compDouble(val, 6.74) < 0) { vision += "4.0";
        } else if (Util::compDouble(val, 5.25) >= 0 && Util::compDouble(val, 5.74) < 0) { vision += "4.1";
        } else if (Util::compDouble(val, 4.75) >= 0 && Util::compDouble(val, 5.24) < 0) { vision += "4.2";
        } else if (Util::compDouble(val, 4.25) >= 0 && Util::compDouble(val, 4.74) < 0) { vision += "4.3";
        } else if (Util::compDouble(val, 3.75) >= 0 && Util::compDouble(val, 4.24) < 0) { vision += "4.4";
        } else if (Util::compDouble(val, 3.25) >= 0 && Util::compDouble(val, 3.74) < 0) { vision += "4.5";
        } else if (Util::compDouble(val, 2.75) >= 0 && Util::compDouble(val, 3.24) < 0) { vision += "4.6";
        } else if (Util::compDouble(val, 2.25) >= 0 && Util::compDouble(val, 2.74) < 0) { vision += "4.7";
        } else if (Util::compDouble(val, 1.75) >= 0 && Util::compDouble(val, 2.24) < 0) { vision += "4.8";
        } else if (Util::compDouble(val, 1.25) >= 0 && Util::compDouble(val, 1.74) < 0) { vision += "4.9";
        } else if (Util::compDouble(val, 0.75) >= 0 && Util::compDouble(val, 1.24) < 0) { vision += "5.0";
        } else if (Util::compDouble(val, 0.25) >= 0 && Util::compDouble(val, 0.74) < 0) { vision += "5.1";
        } else if (Util::compDouble(val, 0.00) >= 0 && Util::compDouble(val, 0.24) < 0) { vision += "5.2";
        }
    } else if (visionNotation_Decimal == _type) {
        if (Util::compDouble(val, 6.75) >= 0) { vision += "<0.1";
        } else if (Util::compDouble(val, 6.25) >= 0 && Util::compDouble(val, 6.74) < 0) { vision += "0.10";
        } else if (Util::compDouble(val, 5.25) >= 0 && Util::compDouble(val, 5.74) < 0) { vision += "0.12";
        } else if (Util::compDouble(val, 4.75) >= 0 && Util::compDouble(val, 5.24) < 0) { vision += "0.15";
        } else if (Util::compDouble(val, 4.25) >= 0 && Util::compDouble(val, 4.74) < 0) { vision += "0.20";
        } else if (Util::compDouble(val, 3.75) >= 0 && Util::compDouble(val, 4.24) < 0) { vision += "0.25";
        } else if (Util::compDouble(val, 3.25) >= 0 && Util::compDouble(val, 3.74) < 0) { vision += "0.30";
        } else if (Util::compDouble(val, 2.75) >= 0 && Util::compDouble(val, 3.24) < 0) { vision += "0.40";
        } else if (Util::compDouble(val, 2.25) >= 0 && Util::compDouble(val, 2.74) < 0) { vision += "0.50";
        } else if (Util::compDouble(val, 1.75) >= 0 && Util::compDouble(val, 2.24) < 0) { vision += "0.60";
        } else if (Util::compDouble(val, 1.25) >= 0 && Util::compDouble(val, 1.74) < 0) { vision += "0.80";
        } else if (Util::compDouble(val, 0.75) >= 0 && Util::compDouble(val, 1.24) < 0) { vision += "1.00";
        } else if (Util::compDouble(val, 0.25) >= 0 && Util::compDouble(val, 0.74) < 0) { vision += "1.20";
        } else if (Util::compDouble(val, 0.00) >= 0 && Util::compDouble(val, 0.24) < 0) { vision += "1.50";
        }
    }

    return vision;
}

