/// class CCalcImgInfo

CCalcImgInfo::CCalcImgInfo(QObject *parent) : QObject(parent)
{

}

CCalcImgInfo::~CCalcImgInfo()
{
    reset();
}

void CCalcImgInfo::reset()
{
    mean = -1;
    stdDev = -1;
    clarity = -1;
}

void CCalcImgInfo::slotCalcImgInfo(unsigned char *_img_data)
{
    static bool is_save = false;

    cv::Mat img(IMG_HEIGHT, IMG_WIDTH, CV_8UC1, _img_data);

    if (is_save) {
        std::string file_path = QString("/media/photo/%1.bmp").arg(QTime::currentTime().toString("HHmmss")).toStdString();
        cv::imwrite(file_path, img);
        is_save = false;
    }

    clarity = AlgorithmThread::calcClarity(img);
    AlgorithmThread::calcMeanStdDev(img, mean, stdDev);
}
